/**
 * Shape of data submitted by the login form.
 * Used for authentication (sign in).
 */
export interface LoginFormFields
{
    /** User email address */
    email: string;
    /** User password */
    password: string;
}

/**
 * Shape of data submitted by the registration form.
 * Combines Identity fields and Company fields,
 * plus UI-only fields (e.g., passwordConfirm).
 *
 * Handle is auto-generated by the backend from firstname + lastname.
 */
export interface RegistrationFormFields
{
    // --- Identity Details ---
    /** First name of the user */
    firstname: string;
    /** Last name of the user */
    lastname: string;
    /** User email for account */
    email: string;
    /** Password for login */
    password: string;
    /** UI-only: password confirmation */
    passwordConfirm: string;

    // --- Company Details ---
    /** Display name of the user's company/organisation */
    companyName: string;

    // --- Jurisdiction ---
    /**
     * Country the account is registered in, as a UUID.
     *
     * This is the account's jurisdiction, not a display preference: region-scoped business
     * rules are evaluated against it and the terms are acknowledged under it. Defaulted from
     * the IP-based suggestion and shown, rather than inferred silently — a VPN or a trip
     * would otherwise decide it.
     */
    countryId: string;

    // --- T&Cs ---
    /** User has acknowledged the terms and conditions of the application */
    acknowledgedTerms: boolean;
}

/**
 *
 */
export interface ProvideEmailFormFields
{
    /** User email for account */
    email: string;
}

/**
 *
 */
export interface ProvideCodeFormFields
{
    /** User email for account */
    email?: string;

    /** User email for account */
    code: string;
}
